import '../entities/movement.dart';

/// Writes Movements generated by the app itself (e.g. recurring bills).
abstract interface class MovementWriter {
  /// Writes [tx] under [id] only if nothing was written there before; see
  /// TransactionRepository.createIfAbsent for what [recurring] adds.
  Future<void> createIfAbsent(String householdId, String id, Movement tx, {bool recurring = false});
}
